"""Deterministic generation of distinct record ids."""

import random


def make_ids(n: int, seed: int) -> list[int]:
    """Return n distinct record ids, identical on every call with the same seed.

    Uses a private, seeded random.Random instance so the global random state is
    never read or modified. Performs no I/O.
    """
    rng = random.Random(seed)
    return rng.sample(range(1, 2**32), n)


def test_make_ids_length() -> None:
    assert len(make_ids(5, seed=1)) == 5


def test_make_ids_distinct() -> None:
    ids = make_ids(100, seed=7)
    assert len(set(ids)) == 100


def test_make_ids_reproducible() -> None:
    assert make_ids(10, seed=42) == make_ids(10, seed=42)


def test_make_ids_zero() -> None:
    assert make_ids(0, seed=3) == []


def test_make_ids_element_type() -> None:
    assert all(isinstance(i, int) for i in make_ids(8, seed=9))
